mapper.update:
update course
name = #{name}, type = #{type}, teacher_id = #{teacherId}, score = #{score}, num = #{num}, room = #{room}, week = #{week}, segment = #{segment}, status = #{status},
where id = #{id}

mapper.select:
select c.*, t.name as teacherName
from course c
left join teacher t on c.teacher_id = t.id

    and c.id = #{id}
    and c.name like concat('%', #{name}, '%')
    and c.type like concat('%', #{type}, '%')
    and c.teacher_id = #{teacherId}
    and c.status = #{status}

order by c.id desc
